import{_ as r,C as d,o,c as s,j as t,a as n,E as i,a3 as c}from"./chunks/framework.D6kVjW99.js";const b=JSON.parse('{"title":"Back office error messages (index)","description":"Alphabetical index of back office error messages: what the message says, why it appears and the tutorial with the solution.","frontmatter":{"title":"Back office error messages (index)","description":"Alphabetical index of back office error messages: what the message says, why it appears and the tutorial with the solution.","order":90,"role":["TOUS"],"appareil":"WEB","duree":"2 minutes","objectif":"Find, in a few seconds, the cause of an error message and the page that explains what to do.","prerequis":["Note the exact message shown on screen (or take a screenshot of it)."],"parcours":["H9-09"],"capturesLangue":{},"capturesCouvertes":true},"headers":[],"relativePath":"en/guide/depannage/messages-d-erreur.md","filePath":"en/guide/depannage/messages-d-erreur.md","lastUpdated":1794455775000}'),h={name:"en/guide/depannage/messages-d-erreur.md"};function l(u,e,g,m,p,f){const a=d("FicheTuto");return o(),s("div",null,[e[0]||(e[0]=t("h1",{id:"back-office-error-messages-index",tabindex:"-1"},[n("Back office error messages (index) "),t("a",{class:"header-anchor",href:"#back-office-error-messages-index","aria-label":'Permalink to "Back office error messages (index)"'},"​")],-1)),i(a),e[1]||(e[1]=c('<p>A message appears in red under a form, in a banner or in a dialog? Look it up below (or type a few words of the message in the help center <strong>search</strong>, at the top of the page). Each row gives the likely cause and the tutorial that explains the solution step by step.</p><p>Messages are sorted alphabetically by their first word, as displayed in English, ignoring quotation marks and accents. Messages received by third-party software through the public API stay in French: they are listed with their exact French text, sorted with the others, and the Cause column gives their meaning. The parts that change from one case to another (product name, number, name of your plan) are replaced with <strong>…</strong> or shown with an example from the demo business.</p><h2 id="message-families" tabindex="-1">Message families <a class="header-anchor" href="#message-families" aria-label="Permalink to &quot;Message families&quot;">​</a></h2><p>Before looking for a specific message, recognize its family: what to do is often the same.</p><table tabindex="0"><thead><tr><th>The message contains…</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td><strong>changed elsewhere</strong>, <strong>in the meantime</strong>, <strong>Outdated version</strong></td><td>Someone else (or you, in another tab) saved the same page while you were editing it. Vendora refuses to overwrite their work.</td><td>The latest version is usually reloaded automatically: redo your changes, then save. Otherwise, reload the page.</td></tr><tr><td><strong>Manager role required</strong>, <strong>Owner or Administrator role required</strong>, <strong>Restricted to…</strong> / <strong>Reserved for…</strong>, <strong>Only the owner…</strong>, <strong>Read-only: …</strong></td><td>Your role on the displayed store does not allow this action.</td><td>Check the store selected at the top of the page, then ask the owner to change your role (<a href="/VendoraSystem-docs/aide/en/guide/reglages/equipe">Build your team</a>).</td></tr><tr><td><strong>is not included in the … plan</strong>, <strong>plan limit reached</strong></td><td>Your Vendora subscription does not include this module, or its number of stores or devices has been reached.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/abonnement">Manage your subscription</a>, or contact Vendora.</td></tr><tr><td><strong>Read-only account</strong>, <strong>Account suspended</strong></td><td>The subscription is suspended or canceled: the back office can be viewed but no longer changed. Registers keep selling.</td><td><a href="/VendoraSystem-docs/aide/en/guide/depannage/compte-suspendu">Account suspended, end of trial</a>.</td></tr><tr><td><strong>Unable to load…</strong>, <strong>Could not load</strong>, <strong>… unavailable</strong>, <strong>the server is not responding</strong>, <strong>check your connection</strong></td><td>The back office got no response from the server: Internet connection lost, or service temporarily unavailable.</td><td>Check your connection, wait a few moments, then reload the page (F5 key).</td></tr><tr><td><strong>… denied.</strong> / <strong>… refused.</strong> followed by an explanation (e.g. <strong>Save refused.</strong>, <strong>Publication denied.</strong>)</td><td>The server refused the operation; the second sentence says why.</td><td>Look up the second sentence in the index below.</td></tr><tr><td><strong>Could not …</strong> / <strong>… failed.</strong> on its own (e.g. <strong>Could not disable.</strong>, <strong>Export failed.</strong>)</td><td>The operation did not go through, with no further detail (often a network outage).</td><td>Reload the page and try again; if it persists, note the time and contact support.</td></tr></tbody></table><h2 id="alphabetical-index" tabindex="-1">Alphabetical index <a class="header-anchor" href="#alphabetical-index" aria-label="Permalink to &quot;Alphabetical index&quot;">​</a></h2><p><strong>Jump to letter:</strong> <a href="#lettre-0-9">0–9</a> · <a href="#lettre-a">A</a> · <a href="#lettre-c">C</a> · <a href="#lettre-d">D</a> · <a href="#lettre-e">E</a> · <a href="#lettre-f">F</a> · <a href="#lettre-i">I</a> · <a href="#lettre-l">L</a> · <a href="#lettre-m">M</a> · <a href="#lettre-n">N</a> · <a href="#lettre-o">O</a> · <a href="#lettre-p">P</a> · <a href="#lettre-r">R</a> · <a href="#lettre-s">S</a> · <a href="#lettre-t">T</a> · <a href="#lettre-u">U</a> · <a href="#lettre-v">V</a></p><h2 id="lettre-0-9" tabindex="-1">0–9 <a class="header-anchor" href="#lettre-0-9" aria-label="Permalink to &quot;0–9 {#lettre-0-9}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>5 product(s) use this rate: move them to another rate first</td><td>You are disabling or deleting a VAT rate that products still use.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/taux-de-tva">Manage VAT rates (default, reassignment)</a></td></tr></tbody></table><h2 id="lettre-a" tabindex="-1">A <a class="header-anchor" href="#lettre-a" aria-label="Permalink to &quot;A {#lettre-a}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>A product sold by weight cannot have variants</td><td>Selling by weight and variants cannot be combined on the same product.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/variantes">Products with variants (size, color, flavor)</a></td></tr><tr><td>A reason is required to reject an event.</td><td>Rejecting a sync event requires a reason.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/synchronisation">Handle rejected sync events</a></td></tr><tr><td>A shipped transfer cannot be canceled: receive it, with a full discrepancy if needed</td><td>Once shipped, a transfer ends with its receipt.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/transferts">Transfer stock between stores</a></td></tr><tr><td>Accepted formats: PNG, JPEG or WebP.</td><td>The logo (or kiosk image) is neither a PNG, a JPEG nor a WebP.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/apparence">Customize the appearance (logo, colors, kiosk)</a></td></tr><tr><td>Account suspended or canceled: no new device can be paired. Contact Vendora.</td><td>Pairing is blocked as long as the account is suspended.</td><td><a href="/VendoraSystem-docs/aide/en/guide/depannage/compte-suspendu">Account suspended, end of trial</a></td></tr><tr><td>Alerts unavailable (Manager role required on this store).</td><td>Your role on the displayed store does not give access to the dashboard alerts.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/tableau-de-bord">Discover the dashboard and the “Getting started” list</a></td></tr><tr><td>Already handled elsewhere — list reloaded.</td><td>Another manager handled this duplicate customer before you.</td><td><a href="/VendoraSystem-docs/aide/en/guide/clients/doublons-clients">Merge duplicate customers</a></td></tr><tr><td>“Anti-fraud” is not included in the Restaurant plan. Contact Vendora to add it.</td><td>The requested module is not part of your plan (the module and plan names vary).</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/anti-fraude">Monitor anti-fraud</a></td></tr><tr><td>At least 8 characters.</td><td>The password chosen at sign-up is too short.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/creer-son-espace">Create your Vendora account</a></td></tr><tr><td>At least one name, id or barcode column is required</td><td>The file does not allow products to be recognized.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/importer-catalogue-csv">Import your catalog from a CSV file</a></td></tr><tr><td>At least one recipient is required to enable the summary</td><td>The daily summary is enabled without an email address.</td><td><a href="/VendoraSystem-docs/aide/en/guide/pilotage/recapitulatif-quotidien">Receive the daily summary</a></td></tr><tr><td>At least one step must be required (minimum ≥ 1).</td><td>All steps of the combo are optional.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/formules">Create a combo (menu) with steps</a></td></tr><tr><td>At least one tier to activate loyalty</td><td>The loyalty program is enabled without a reward tier.</td><td><a href="/VendoraSystem-docs/aide/en/guide/clients/fidelite">Set up a loyalty program</a></td></tr><tr><td>Axis “Parfum”: at least one value</td><td>A variant axis has no value.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/variantes">Products with variants (size, color, flavor)</a></td></tr></tbody></table><h2 id="lettre-c" tabindex="-1">C <a class="header-anchor" href="#lettre-c" aria-label="Permalink to &quot;C {#lettre-c}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Category used by …: remove it first</td><td>The category you want to delete still contains products.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/categories">Organize categories</a></td></tr><tr><td>Certificate only available for stores subject to the French tax module</td><td>The tax certificate only concerns stores located in France.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/conformite-fiscale">Tax compliance: integrity, closures, archives</a></td></tr><tr><td>Change refused — Read-only account (subscription suspended or canceled): sales continue on your registers. Contact Vendora from the Subscription page.</td><td>A change was attempted while the subscription is suspended.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/abonnement">Manage your Vendora subscription and invoices</a></td></tr><tr><td>Changed elsewhere — reload.</td><td>The product was saved by someone else while you were editing it (a duplicate barcode or scale code shows its own reason instead).</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/creer-un-produit">Create and edit a product</a></td></tr><tr><td>Choose a VAT rate.</td><td>The product has no VAT rate.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/creer-un-produit">Create and edit a product</a></td></tr><tr><td>Choose an accredited platform before enabling sending</td><td>E-reporting is enabled without a chosen e-invoicing platform.</td><td><a href="/VendoraSystem-docs/aide/en/guide/pilotage/e-reporting">VAT e-reporting for sales to consumers (France)</a></td></tr><tr><td>Code expired or already used — generate a new one in the back office.</td><td>The pairing code has expired (15 minutes) or has already been used (same text on the device and in the server responses).</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/appairer-un-appareil">Pair a register or a phone (code, QR)</a></td></tr><tr><td>Combo changed elsewhere in the meantime: reload to start from the latest version (your unpublished changes will be lost).</td><td>The combo was published by someone else while you were editing it.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/formules">Create a combo (menu) with steps</a></td></tr><tr><td>Configuration changed in the meantime</td><td>The kiosk was changed by someone else at the same time as you.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/bornes">Monitor your kiosks</a></td></tr><tr><td>Correction denied. Invalid PIN</td><td>The manager PIN entered to correct a movement is wrong.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/journal-du-stock">Understand the stock log</a></td></tr><tr><td>Correction denied. Reason required</td><td>A stock movement correction must be justified.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/journal-du-stock">Understand the stock log</a></td></tr><tr><td>Could not disable.</td><td>The server did not respond when disabling the kiosk.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/bornes">Monitor your kiosks</a></td></tr><tr><td>Could not load</td><td>The page got no response from the server: reload it.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/liste-des-produits">Search, filter, activate / deactivate products</a></td></tr><tr><td>Creation denied. Email already in use</td><td>A team member already has this email.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/equipe">Build your team: roles, invitations, PINs</a></td></tr><tr><td>Creation denied. PIN already used in this store, choose another one</td><td>Two members of the same store cannot have the same PIN.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/equipe">Build your team: roles, invitations, PINs</a></td></tr><tr><td>Currency can no longer change after the store&#39;s first sale</td><td>A store&#39;s currency is locked from its first sale.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/magasins">Manage your stores (create, edit, archive)</a></td></tr><tr><td>Customer anonymized: the record can no longer be edited</td><td>The record has been anonymized (right to erasure): this is permanent.</td><td><a href="/VendoraSystem-docs/aide/en/guide/clients/fiches-clients">Create and find your customers</a></td></tr></tbody></table><h2 id="lettre-d" tabindex="-1">D <a class="header-anchor" href="#lettre-d" aria-label="Permalink to &quot;D {#lettre-d}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Device name required</td><td>The device to pair has no name.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/appareils">Manage your devices (rename, change role, replace, revoke)</a></td></tr></tbody></table><h2 id="lettre-e" tabindex="-1">E <a class="header-anchor" href="#lettre-e" aria-label="Permalink to &quot;E {#lettre-e}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>E-reporting is only for stores on the FR fiscal module (France)</td><td>E-reporting only concerns stores in France.</td><td><a href="/VendoraSystem-docs/aide/en/guide/pilotage/e-reporting">VAT e-reporting for sales to consumers (France)</a></td></tr><tr><td>Empty file: the first line must contain the headers</td><td>The CSV file is empty or has no header row.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/importer-catalogue-csv">Import your catalog from a CSV file</a></td></tr><tr><td>Accounting exports: Owner or Administrator role required</td><td>Only the owner and administrators download accounting exports.</td><td><a href="/VendoraSystem-docs/aide/en/guide/pilotage/exports-comptables">Export for your accountant (journals and FEC)</a></td></tr></tbody></table><h2 id="lettre-f" tabindex="-1">F <a class="header-anchor" href="#lettre-f" aria-label="Permalink to &quot;F {#lettre-f}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>File too large (5 MB max)</td><td>The uploaded file (product photo) is larger than 5 MB.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/photos-produit">Add photos to a product</a></td></tr><tr><td>File too long: 10,000 rows at most</td><td>The catalog import file has more than 10,000 rows: split it.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/importer-catalogue-csv">Import your catalog from a CSV file</a></td></tr><tr><td>First finish this store&#39;s ongoing transfers: …</td><td>A store cannot be archived with transfers in progress.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/magasins">Manage your stores (create, edit, archive)</a></td></tr><tr><td>First revoke this store&#39;s active devices: …</td><td>A store cannot be archived while devices are paired to it.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/magasins">Manage your stores (create, edit, archive)</a></td></tr><tr><td>Format not accepted (…): PNG, JPEG or WebP accepted</td><td>The uploaded file (photo, logo) is in another format, named in parentheses (HEIC, GIF, SVG+XML…).</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/photos-produit">Add photos to a product</a></td></tr></tbody></table><h2 id="lettre-i" tabindex="-1">I <a class="header-anchor" href="#lettre-i" aria-label="Permalink to &quot;I {#lettre-i}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Import already applied</td><td>The preview of this import has already been applied: run a new analysis for a new import.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/importer-catalogue-csv">Import your catalog from a CSV file</a></td></tr><tr><td>Incorrect email or password.</td><td>Wrong credentials, or back office access not enabled for this account.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/se-connecter">Sign in to the back office, forgotten password</a></td></tr><tr><td>Initial stock already entered: correct it with an inventory adjustment</td><td>Initial stock can only be entered once per product.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/valeur-du-stock">Value your stock and enter initial stock</a></td></tr><tr><td>Invalid pairing code — check what you typed.</td><td>On the device: the code typed does not match any generated code.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/appairer-un-appareil">Pair a register or a phone (code, QR)</a></td></tr><tr><td>Invalid PIN</td><td>The manager PIN entered to confirm the operation is wrong.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/suivre-son-stock">Track your stock and stockouts</a></td></tr><tr><td>Invitation already accepted</td><td>The invitation link has already been used: sign in as usual.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/accepter-une-invitation">Accept an invitation</a></td></tr><tr><td>Invitation created for …, but the email was not sent (provider not configured): use “Resend” later.</td><td>The invitation exists but the email could not be sent.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/equipe">Build your team: roles, invitations, PINs</a></td></tr><tr><td>Invitation denied. You cannot invite a Administrator (a role above yours) to this store</td><td>You can only invite roles lower than or equal to your own.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/equipe">Build your team: roles, invitations, PINs</a></td></tr><tr><td>Invoice … already recorded for this supplier</td><td>This supplier invoice number already exists.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/dettes-fournisseurs">Track supplier invoices and payables</a></td></tr></tbody></table><h2 id="lettre-l" tabindex="-1">L <a class="header-anchor" href="#lettre-l" aria-label="Permalink to &quot;L {#lettre-l}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Limite de 600 requêtes par minute atteinte</td><td>Shown in French; it means “Limit of 600 requests per minute reached”. An integration calls the API too often with this key.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/cles-api">Create API keys (integrations)</a></td></tr><tr><td>Link already used or replaced — request a new one (“Forgot password?”)</td><td>The reset link has already been used or a newer link has been sent.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/se-connecter">Sign in to the back office, forgotten password</a></td></tr><tr><td>Link expired — request a new one (“Forgot password?”)</td><td>The password reset link has expired.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/se-connecter">Sign in to the back office, forgotten password</a></td></tr><tr><td>Live view is reserved for this store&#39;s managers.</td><td>The live dashboard is reserved for managers.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/tableau-de-bord">Discover the dashboard and the “Getting started” list</a></td></tr><tr><td>Logo too large (2 MB max).</td><td>The logo is larger than 2 MB.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/apparence">Customize the appearance (logo, colors, kiosk)</a></td></tr><tr><td>Lot number and use-by date are required for “…” (product tracked for expiry).</td><td>At receiving, a line for a product tracked for expiry has no lot number or use-by date.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/bons-de-commande">Place a purchase order and receive it</a></td></tr></tbody></table><h2 id="lettre-m" tabindex="-1">M <a class="header-anchor" href="#lettre-m" aria-label="Permalink to &quot;M {#lettre-m}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Manager PIN required: enter the PIN of a store manager to confirm.</td><td>The PIN field was empty (or you have not set your PIN yet).</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/suivre-son-stock">Track your stock and stockouts</a></td></tr><tr><td>Manager role required</td><td>Your role on this store does not allow this action (import, setting…).</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/importer-catalogue-csv">Import your catalog from a CSV file</a></td></tr><tr><td>Manager role required for this store</td><td>You are a cashier or waiter on this store, or you have no role there.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/equipe">Build your team: roles, invitations, PINs</a></td></tr><tr><td>Missing daily closures (7/37): generate the due closures before archiving</td><td>Some days have no closure, so the tax archive cannot be produced.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/conformite-fiscale">Tax compliance: integrity, closures, archives</a></td></tr><tr><td>“Multiple stores” is not included in your plan: existing data remains viewable; creating and configuring require a plan that includes it.</td><td>Your plan does not include multi-store.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/abonnement">Manage your Vendora subscription and invoices</a></td></tr></tbody></table><h2 id="lettre-n" tabindex="-1">N <a class="header-anchor" href="#lettre-n" aria-label="Permalink to &quot;N {#lettre-n}&quot;">​</a></h2><p>No message starts with N in English: look under the next letters.</p><h2 id="lettre-o" tabindex="-1">O <a class="header-anchor" href="#lettre-o" aria-label="Permalink to &quot;O {#lettre-o}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Only a partly received order can be closed.</td><td>Only a partly received purchase order has a remainder to close.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/bons-de-commande">Place a purchase order and receive it</a></td></tr><tr><td>Only the owner and admins can edit this reference data.</td><td>VAT rates are reserved for the owner and administrators.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/taux-de-tva">Manage VAT rates (default, reassignment)</a></td></tr><tr><td>Only the owner grants or revokes a delegation.</td><td>Access for Vendora support is decided by the owner.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/acces-vendora">Authorize Vendora support (delegated access)</a></td></tr><tr><td>Only the store owner configures payment connectors</td><td>Only the owner connects the payment accounts.</td><td><a href="/VendoraSystem-docs/aide/en/guide/caisse-paiements/connecteurs-de-paiement">Connect a payment connector (card terminal, online payment)</a></td></tr><tr><td>Only the store owner designates the main register</td><td>Only the owner chooses the main register for table checkout.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/appairer-un-appareil">Pair a register or a phone (code, QR)</a></td></tr><tr><td>Outdated version: current …, received …</td><td>You saved an older version than the server&#39;s (simultaneous edit): reload the page and make the change again.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/creer-un-produit">Create and edit a product</a></td></tr><tr><td>Owner or Administrator role required</td><td>Action reserved for the owner and administrators.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/conformite-fiscale">Tax compliance: integrity, closures, archives</a></td></tr></tbody></table><h2 id="lettre-p" tabindex="-1">P <a class="header-anchor" href="#lettre-p" aria-label="Permalink to &quot;P {#lettre-p}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Page restricted to the owner and admins.</td><td>Your role does not give access to the subscription.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/abonnement">Manage your Vendora subscription and invoices</a></td></tr><tr><td>Password: 8 characters minimum</td><td>The new password is too short.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/se-connecter">Sign in to the back office, forgotten password</a></td></tr><tr><td>Period not closed: the end must be before today</td><td>A tax archive covers a finished period.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/conformite-fiscale">Tax compliance: integrity, closures, archives</a></td></tr><tr><td>Phone already used by …</td><td>Another customer already has this number (probable duplicate).</td><td><a href="/VendoraSystem-docs/aide/en/guide/clients/fiches-clients">Create and find your customers</a></td></tr><tr><td>PIN already used in this store, choose another one</td><td>The PIN chosen when activating the invitation is already taken.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/accepter-une-invitation">Accept an invitation</a></td></tr><tr><td>Primary color in #RRGGBB format.</td><td>The color entered is not a six-digit hexadecimal code.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/apparence">Customize the appearance (logo, colors, kiosk)</a></td></tr><tr><td>Publication denied. Table “T9”: position already taken in “Salle”</td><td>Two tables are placed at the same spot on the plan.</td><td><a href="/VendoraSystem-docs/aide/en/guide/restaurant/plan-de-salle">Draw your floor plan (zones, tables)</a></td></tr><tr><td>Publication denied. The main register must be an active register (REGISTER) in this store</td><td>The designated main register is revoked, belongs to another store or is not a register.</td><td><a href="/VendoraSystem-docs/aide/en/guide/restaurant/encaissement-a-la-table">Choose how payment is taken at the table</a></td></tr></tbody></table><h2 id="lettre-r" tabindex="-1">R <a class="header-anchor" href="#lettre-r" aria-label="Permalink to &quot;R {#lettre-r}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Read-only account (subscription suspended or canceled): sales continue on your registers. Contact Vendora from the Subscription page.</td><td>The subscription is suspended or canceled: the back office refuses any change.</td><td><a href="/VendoraSystem-docs/aide/en/guide/depannage/compte-suspendu">Account suspended, end of trial</a></td></tr><tr><td>Read-only account: change denied.</td><td>Same cause, short message shown in a banner.</td><td><a href="/VendoraSystem-docs/aide/en/guide/depannage/compte-suspendu">Account suspended, end of trial</a></td></tr><tr><td>Reference already used by another product</td><td>Two products cannot have the same reference (upper and lower case are the same).</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/creer-un-produit">Create and edit a product</a></td></tr><tr><td>Read-only: only the owner and administrators can change these settings.</td><td>Your role lets you view the page but not change it.</td><td><a href="/VendoraSystem-docs/aide/en/guide/pilotage/recapitulatif-quotidien">Receive the daily summary</a></td></tr><tr><td>Reader ID required outside simulation</td><td>The kiosk payment terminal is set to Sandbox or Production without a reader ID.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/bornes">Monitor your kiosks</a></td></tr><tr><td>Reason required to handle an alert</td><td>An anti-fraud alert is handled with a reason.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/anti-fraude">Monitor anti-fraud</a></td></tr><tr><td>Reserved for the store&#39;s managers.</td><td>Page limited to managers, administrators and the owner.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/bornes">Monitor your kiosks</a></td></tr><tr><td>Restaurant plan limit reached: 1 store(s). Contact Vendora to add more.</td><td>Your plan does not allow another store (the plan name and the number vary).</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/magasins">Manage your stores (create, edit, archive)</a></td></tr><tr><td>Restaurant plan limit reached: 6 sales device(s) (kiosks excluded). Upgrade to a higher plan or add an extra device (Subscription page).</td><td>All the sales devices in your plan are in use.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/appairer-un-appareil">Pair a register or a phone (code, QR)</a></td></tr><tr><td>Restricted to the owner and administrators.</td><td>Action limited to the Owner and Administrator roles.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/cles-api">Create API keys (integrations)</a></td></tr><tr><td>Role change denied. You cannot change your own role</td><td>Nobody can change their own role, not even the owner.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/equipe">Build your team: roles, invitations, PINs</a></td></tr><tr><td>… row(s) with errors (the catalog may have changed since the analysis): fix the file and run the import again</td><td>The catalog changed between the preview and applying the import.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/importer-catalogue-csv">Import your catalog from a CSV file</a></td></tr></tbody></table><h2 id="lettre-s" tabindex="-1">S <a class="header-anchor" href="#lettre-s" aria-label="Permalink to &quot;S {#lettre-s}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Save denied. A product with variants has no barcode, scale code or sale by weight: they are set on each variant</td><td>Codes are entered on each variant, not on the parent product.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/vente-au-poids">Sell by weight and scale codes</a></td></tr><tr><td>Save denied. Barcode already used by another product</td><td>The barcode entered already belongs to another product.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/codes-barres">Barcodes: enter, scan, generate internal codes</a></td></tr><tr><td>Save denied. Codes starting with 20 are reserved for generated internal codes</td><td>Those barcodes are reserved for the codes Vendora generates.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/codes-barres">Barcodes: enter, scan, generate internal codes</a></td></tr><tr><td>Save denied. Manager role required for this store</td><td>Your role does not allow you to edit this store&#39;s catalog.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/creer-un-produit">Create and edit a product</a></td></tr><tr><td>Save denied. Scale code already used by another product</td><td>The scale code (PLU) entered already belongs to another product.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/vente-au-poids">Sell by weight and scale codes</a></td></tr><tr><td>Sign-up closed: contact Vendora to open your account</td><td>Self sign-up is disabled: the account is created by the Vendora team.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/creer-son-espace">Create your Vendora account</a></td></tr><tr><td>Store archived: no new transfers</td><td>The chosen store is archived.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/transferts">Transfer stock between stores</a></td></tr><tr><td>Store name required</td><td>The store has no name.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/magasins">Manage your stores (create, edit, archive)</a></td></tr><tr><td>Supplier currency (…) differs from the store&#39;s (…): multi-currency not supported</td><td>The supplier invoices in a different currency from the store.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/bons-de-commande">Place a purchase order and receive it</a></td></tr><tr><td>Supplier deactivated: no longer available for a new order</td><td>The chosen supplier has been deactivated.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/fournisseurs">Manage your suppliers and their prices</a></td></tr><tr><td>Surplus of more than 20%: … — confirm</td><td>The quantity received is well above the order.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/bons-de-commande">Place a purchase order and receive it</a></td></tr></tbody></table><h2 id="lettre-t" tabindex="-1">T <a class="header-anchor" href="#lettre-t" aria-label="Permalink to &quot;T {#lettre-t}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Tab not settled (…): collect the payment or write it off first</td><td>You want to anonymize or deactivate a customer who still owes money.</td><td><a href="/VendoraSystem-docs/aide/en/guide/clients/fiches-clients">Create and find your customers</a></td></tr><tr><td>Table “T3” already exists in this store.</td><td>Two tables in the same store cannot have the same name.</td><td><a href="/VendoraSystem-docs/aide/en/guide/restaurant/plan-de-salle">Draw your floor plan (zones, tables)</a></td></tr><tr><td>The category contains 2 subcategory(ies): move or delete them first</td><td>A category with subcategories cannot be deleted.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/categories">Organize categories</a></td></tr><tr><td>The default rate cannot be disabled: first choose another default rate</td><td>The default VAT rate must stay active.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/taux-de-tva">Manage VAT rates (default, reassignment)</a></td></tr><tr><td>The email address is invalid.</td><td>The email entered is not in a valid format.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/creer-son-espace">Create your Vendora account</a></td></tr><tr><td>The file could not be parsed.</td><td>The file is not a readable CSV (encoding, separator, format).</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/importer-catalogue-csv">Import your catalog from a CSV file</a></td></tr><tr><td>The fingerprint does not match the content: this Z report may have been altered</td><td>The browser recalculated the Z report fingerprint and did not get the same one.</td><td><a href="/VendoraSystem-docs/aide/en/guide/caisse-paiements/rapports-z">Read and download Z reports</a></td></tr><tr><td>The last active store cannot be archived</td><td>There must always be at least one store in service.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/magasins">Manage your stores (create, edit, archive)</a></td></tr><tr><td>The minimum exceeds the maximum.</td><td>The limits of a combo step are reversed.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/formules">Create a combo (menu) with steps</a></td></tr><tr><td>The name is required.</td><td>The product has no name.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/creer-un-produit">Create and edit a product</a></td></tr><tr><td>The payment exceeds the invoice&#39;s remaining balance (…).</td><td>The payment entered exceeds the amount still due on the supplier invoice (shown in parentheses).</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/dettes-fournisseurs">Track supplier invoices and payables</a></td></tr><tr><td>The PIN must be 4 to 6 digits.</td><td>The PIN entered is too short, too long or contains something other than digits.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/equipe">Build your team: roles, invitations, PINs</a></td></tr><tr><td>The plan was changed elsewhere: the latest version has been reloaded, reapply your changes.</td><td>Someone else published the floor plan while you were editing it.</td><td><a href="/VendoraSystem-docs/aide/en/guide/restaurant/plan-de-salle">Draw your floor plan (zones, tables)</a></td></tr><tr><td>The policy was changed elsewhere: the latest version has been reloaded.</td><td>The table checkout policy was published by someone else.</td><td><a href="/VendoraSystem-docs/aide/en/guide/restaurant/encaissement-a-la-table">Choose how payment is taken at the table</a></td></tr><tr><td>The prep stations were changed elsewhere: the latest version has been reloaded.</td><td>The prep stations were published by someone else.</td><td><a href="/VendoraSystem-docs/aide/en/guide/restaurant/postes-de-preparation">Create prep stations and route products (kitchen, bar)</a></td></tr><tr><td>The simulated terminal is not allowed in production.</td><td>The simulated terminal is for testing only.</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/bornes">Monitor your kiosks</a></td></tr><tr><td>The SIREN has 9 digits</td><td>The SIREN entered in the accounting settings is malformed.</td><td><a href="/VendoraSystem-docs/aide/en/guide/pilotage/exports-comptables">Export for your accountant (journals and FEC)</a></td></tr><tr><td>The source store and the destination store must be different</td><td>A transfer takes place between two distinct stores.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/transferts">Transfer stock between stores</a></td></tr><tr><td>This button overflows the grid or overlaps another button.</td><td>The sales screen button goes outside the grid or overlaps another one.</td><td><a href="/VendoraSystem-docs/aide/en/guide/restaurant/ecran-de-vente">Lay out the sales screen (tiles, quick buttons)</a></td></tr><tr><td>This email address already has an account. Sign in or use &quot;Forgot password&quot;.</td><td>The email entered at sign-up matches an existing account.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/creer-son-espace">Create your Vendora account</a></td></tr><tr><td>This link has expired (72 h). Ask your manager to resend the invitation.</td><td>The invitation link is more than three days old.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/accepter-une-invitation">Accept an invitation</a></td></tr><tr><td>This order has already been received: close the remainder instead of canceling it.</td><td>A purchase order that has already been received (even partly) can no longer be canceled.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/bons-de-commande">Place a purchase order and receive it</a></td></tr><tr><td>This purchase order (…) can no longer be edited: only a draft can be edited.</td><td>The order has been sent to the supplier: it can no longer be edited.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/bons-de-commande">Place a purchase order and receive it</a></td></tr><tr><td>This stock count is already validated: reload the page.</td><td>The stock count was validated in the meantime (by you in another tab, or by a colleague).</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/inventaire">Start a stock count and validate it</a></td></tr><tr><td>This store is archived: put it back into service (Stores page) before pairing a device to it.</td><td>The pairing code targets an archived store.</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/appairer-un-appareil">Pair a register or a phone (code, QR)</a></td></tr><tr><td>Three category levels at most</td><td>Categories can be nested three levels deep at most.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/categories">Organize categories</a></td></tr><tr><td>Transfers need at least two active stores.</td><td>With a single store, there is nothing to transfer.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/transferts">Transfer stock between stores</a></td></tr></tbody></table><h2 id="lettre-u" tabindex="-1">U <a class="header-anchor" href="#lettre-u" aria-label="Permalink to &quot;U {#lettre-u}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Unable to load the stock: check your connection, then reload the page.</td><td>The server is not responding: check the connection, then reload.</td><td><a href="/VendoraSystem-docs/aide/en/guide/stock-achats/suivre-son-stock">Track your stock and stockouts</a></td></tr><tr><td>Unable to load the team.</td><td>The team list could not be read (network, permissions).</td><td><a href="/VendoraSystem-docs/aide/en/guide/reglages/equipe">Build your team: roles, invitations, PINs</a></td></tr><tr><td>Unable to sign in: the server is not responding. Check your internet connection, then try again.</td><td>The back office cannot reach the server (network down, service unavailable).</td><td><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/se-connecter">Sign in to the back office, forgotten password</a></td></tr><tr><td>Unknown column(s): …</td><td>The CSV file contains headers that the import does not recognize.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/importer-catalogue-csv">Import your catalog from a CSV file</a></td></tr></tbody></table><h2 id="lettre-v" tabindex="-1">V <a class="header-anchor" href="#lettre-v" aria-label="Permalink to &quot;V {#lettre-v}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>What to do</th></tr></thead><tbody><tr><td>Variant changed elsewhere — reload the product.</td><td>The variant was changed by someone else.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/variantes">Products with variants (size, color, flavor)</a></td></tr><tr><td>VAT rate 7 % not in the list: add it in Catalog › VAT rates</td><td>The requested rate does not exist in your VAT rates yet.</td><td><a href="/VendoraSystem-docs/aide/en/guide/catalogue/prix-par-magasin">Prices and availability per store</a></td></tr></tbody></table><h2 id="can-t-find-your-message" tabindex="-1">Can&#39;t find your message? <a class="header-anchor" href="#can-t-find-your-message" aria-label="Permalink to &quot;Can&#39;t find your message?&quot;">​</a></h2><ul><li>Type a few words of the message in the help center <strong>search</strong>: each tutorial has its own “If it does not work” section with the messages for its page.</li><li>Is the message shown on a <strong>register</strong>, a <strong>floor phone</strong>, a <strong>kitchen display</strong> or a <strong>kiosk</strong>? See <a href="/VendoraSystem-docs/aide/en/guide/depannage/caisse-ne-synchronise-plus">A register no longer syncs</a>, <a href="/VendoraSystem-docs/aide/en/guide/depannage/pin-refuse">PIN refused or locked</a> and <a href="/VendoraSystem-docs/aide/en/guide/depannage/mise-a-jour-requise">“Update required” on the device</a>.</li><li>Still stuck? Note the exact message, the page and the time, then contact Vendora support; the owner can also <a href="/VendoraSystem-docs/aide/en/guide/reglages/acces-vendora">authorize Vendora support</a> to look at your account.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/VendoraSystem-docs/aide/en/guide/depannage/aide-contextuelle">Contextual help “?”</a></li><li><a href="/VendoraSystem-docs/aide/en/guide/bien-demarrer/se-reperer">Find your way around the back office</a></li><li><a href="/VendoraSystem-docs/aide/en/guide/depannage/">The Troubleshooting / FAQ section</a></li></ul>',45))])}const v=r(h,[["render",l]]);export{b as __pageData,v as default};
